/**
 * xui shadcn theme - MUI v9 restyled 1:1 to shadcn/ui defaults.
 * Self-contained: imports only from @mui/material/styles (no relative imports).
 * Token source: apps/showcase/src/index.css generated by shadcn CLI
 * (style radix-nova, base color neutral, css variables).
 */
import { createTheme } from "@mui/material/styles"

// ---------------------------------------------------------------------------
// Module augmentation: shared semantic vocabulary (spec: every future theme
// fills these same slots).
// ---------------------------------------------------------------------------
declare module "@mui/material/styles" {
  // Native background/text slots don't ship *Channel fields (MUI only types
  // them on the vars-internal shape, not the public Palette/PaletteOptions),
  // so we add them here to match what setColorChannel() actually populates.
  interface TypeBackground {
    defaultChannel: string
    paperChannel: string
  }
  interface TypeText {
    primaryChannel: string
    secondaryChannel: string
  }
  interface Palette {
    muted: { main: string; mainChannel: string; contrastText: string }
    accent: { main: string; mainChannel: string; contrastText: string }
    popover: { main: string; mainChannel: string; contrastText: string }
    card: { main: string; mainChannel: string; contrastText: string }
    border: string
    input: string
    ring: string
    dividerChannel: string
  }
  interface PaletteOptions {
    muted?: { main: string; mainChannel?: string; contrastText: string }
    accent?: { main: string; mainChannel?: string; contrastText: string }
    popover?: { main: string; mainChannel?: string; contrastText: string }
    card?: { main: string; mainChannel?: string; contrastText: string }
    border?: string
    input?: string
    ring?: string
    dividerChannel?: string
  }
}

declare module "@mui/material/Button" {
  interface ButtonPropsVariantOverrides {
    link: true
  }
}

// ---------------------------------------------------------------------------
// Design tokens - transcribed from shadcn ground truth. Generated file wins.
// ---------------------------------------------------------------------------
const light = {
  background: "oklch(1 0 0)", // shadcn: --background
  foreground: "oklch(0.145 0 0)", // shadcn: --foreground
  card: "oklch(1 0 0)", // shadcn: --card
  cardForeground: "oklch(0.145 0 0)", // shadcn: --card-foreground
  popover: "oklch(1 0 0)", // shadcn: --popover
  popoverForeground: "oklch(0.145 0 0)", // shadcn: --popover-foreground
  primary: "oklch(0.205 0 0)", // shadcn: --primary
  primaryForeground: "oklch(0.985 0 0)", // shadcn: --primary-foreground
  secondary: "oklch(0.97 0 0)", // shadcn: --secondary
  secondaryForeground: "oklch(0.205 0 0)", // shadcn: --secondary-foreground
  muted: "oklch(0.97 0 0)", // shadcn: --muted
  mutedForeground: "oklch(0.556 0 0)", // shadcn: --muted-foreground
  accent: "oklch(0.97 0 0)", // shadcn: --accent
  accentForeground: "oklch(0.205 0 0)", // shadcn: --accent-foreground
  destructive: "oklch(0.577 0.245 27.325)", // shadcn: --destructive
  border: "oklch(0.922 0 0)", // shadcn: --border
  input: "oklch(0.922 0 0)", // shadcn: --input
  ring: "oklch(0.708 0 0)", // shadcn: --ring
}

const dark = {
  background: "oklch(0.145 0 0)", // shadcn: .dark --background
  foreground: "oklch(0.985 0 0)", // shadcn: .dark --foreground
  card: "oklch(0.205 0 0)", // shadcn: .dark --card
  cardForeground: "oklch(0.985 0 0)", // shadcn: .dark --card-foreground
  popover: "oklch(0.205 0 0)", // shadcn: .dark --popover
  popoverForeground: "oklch(0.985 0 0)", // shadcn: .dark --popover-foreground
  primary: "oklch(0.922 0 0)", // shadcn: .dark --primary
  primaryForeground: "oklch(0.205 0 0)", // shadcn: .dark --primary-foreground
  secondary: "oklch(0.269 0 0)", // shadcn: .dark --secondary
  secondaryForeground: "oklch(0.985 0 0)", // shadcn: .dark --secondary-foreground
  muted: "oklch(0.269 0 0)", // shadcn: .dark --muted
  mutedForeground: "oklch(0.708 0 0)", // shadcn: .dark --muted-foreground
  accent: "oklch(0.269 0 0)", // shadcn: .dark --accent
  accentForeground: "oklch(0.985 0 0)", // shadcn: .dark --accent-foreground
  destructive: "oklch(0.704 0.191 22.216)", // shadcn: .dark --destructive
  border: "oklch(1 0 0 / 10%)", // shadcn: .dark --border
  input: "oklch(1 0 0 / 15%)", // shadcn: .dark --input
  ring: "oklch(0.556 0 0)", // shadcn: .dark --ring
}

// shadcn: --radius: 0.625rem (base token set here as shape.borderRadius).
// The derived per-component scale in apps/showcase/src/index.css is
// MULTIPLICATIVE off this base, not the older subtractive calc(radius - Npx):
//   --radius-sm: calc(var(--radius) * 0.6)
//   --radius-md: calc(var(--radius) * 0.8)
//   --radius-lg: var(--radius)          (1x, i.e. the base itself)
//   --radius-xl: calc(var(--radius) * 1.4)
// Later tasks deriving per-component radii from shape.borderRadius must
// multiply, not subtract.
const RADIUS = "0.625rem"

const FONT_SANS = '"Geist Variable", ui-sans-serif, system-ui, sans-serif'

// shadcn: the installed Button (apps/showcase/src/components/ui/button.tsx,
// style "radix-nova") applies no shadow-xs - or any box-shadow - on any
// variant, state, or color scheme. Verified with getComputedStyle: boxShadow
// resolves to "none" everywhere except the focus-visible ring, which is a
// separate box-shadow layer (see MuiButton below), not this token. Kept as
// a named constant rather than a bare "none" literal so MuiButton's root
// reset stays self-documenting, and consumed there (not exported) since it
// is no longer a bare unused local once a component uses it.
const SHADOW_XS = "none"

// RESOLVED (Task 4): MUI's CSS-variables pipeline derives a companion
// "<slot>Channel" CSS var for every main-shaped palette entry (e.g.
// --mui-palette-primary-mainChannel), a bare "R G B" triplet used to
// alpha-blend overlays via rgba(var(--...Channel) / <alpha>). Deriving it calls
// decomposeColor(), which cannot parse oklch(), so MUI logs a dev warning and
// falls back to the raw oklch string for background.default, background.paper,
// and divider (and silently produces empty/invalid channel CSS for primary,
// secondary, and the other main-shaped oklch slots). Our theme never consumes
// these channel overlays - every interaction state is overridden with
// shadcn's own color-mix(in oklab, ...) - so they are inert, but the warnings
// violate our pristine-console bar and the invalid CSS is still wasteful. MUI
// exposes an escape hatch: setColorChannel()/setColor() skip derivation
// whenever a `<slot>Channel` field is already present next to the color, so
// we precompute it ourselves with deterministic CSS Color 4 / Ottosson
// oklch->sRGB math and hand it over. The `main`/color values themselves stay
// their original oklch strings, so rendered colors are unchanged - only the
// inert *Channel siblings become plain sRGB triplets.
function oklchToRgbTriplet(css: string): string {
  const match = css.match(/oklch\(\s*([-\d.]+)\s+([-\d.]+)\s+([-\d.]+)/)
  if (!match) {
    throw new Error(`oklchToRgbTriplet: cannot parse "${css}"`)
  }
  const L = Number(match[1])
  const C = Number(match[2])
  const H = Number(match[3])

  const h = (H * Math.PI) / 180
  const a = C * Math.cos(h)
  const b = C * Math.sin(h)

  const l_ = L + 0.3963377774 * a + 0.2158037573 * b
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b
  const s_ = L - 0.0894841775 * a - 1.2914855480 * b

  const l = l_ ** 3
  const m = m_ ** 3
  const s = s_ ** 3

  const rLin = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s
  const gLin = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s
  const bLin = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s

  const gamma = (c: number) => (c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055)
  const toByte = (linear: number) => Math.round(Math.min(1, Math.max(0, gamma(linear))) * 255)

  return `${toByte(rLin)} ${toByte(gLin)} ${toByte(bLin)}`
}

function schemePalette(t: typeof light) {
  return {
    background: {
      default: t.background,
      defaultChannel: oklchToRgbTriplet(t.background),
      paper: t.card,
      paperChannel: oklchToRgbTriplet(t.card),
    },
    text: {
      primary: t.foreground,
      primaryChannel: oklchToRgbTriplet(t.foreground),
      secondary: t.mutedForeground,
      secondaryChannel: oklchToRgbTriplet(t.mutedForeground),
    },
    // shadcn has one flat color per role (no separate tonal shades), so
    // light/dark are pinned to main. Without this, MUI's createPalette
    // auto-derives light/dark via lighten()/darken(), which call
    // decomposeColor() - and MUI's decomposeColor only understands
    // #nnn, #nnnnnn, rgb(), rgba(), hsl(), hsla(), color(), NOT oklch().
    // Leaving light/dark undefined here throws at createTheme() time:
    // "MUI: Unsupported `oklch(...)` color."
    primary: {
      main: t.primary,
      mainChannel: oklchToRgbTriplet(t.primary),
      light: t.primary,
      dark: t.primary,
      contrastText: t.primaryForeground,
    },
    secondary: {
      main: t.secondary,
      mainChannel: oklchToRgbTriplet(t.secondary),
      light: t.secondary,
      dark: t.secondary,
      contrastText: t.secondaryForeground,
    },
    error: {
      main: t.destructive,
      mainChannel: oklchToRgbTriplet(t.destructive),
      light: t.destructive,
      dark: t.destructive,
      contrastText: "#ffffff",
    },
    divider: t.border,
    dividerChannel: oklchToRgbTriplet(t.border),
    muted: {
      main: t.muted,
      mainChannel: oklchToRgbTriplet(t.muted),
      contrastText: t.mutedForeground,
    },
    accent: {
      main: t.accent,
      mainChannel: oklchToRgbTriplet(t.accent),
      contrastText: t.accentForeground,
    },
    popover: {
      main: t.popover,
      mainChannel: oklchToRgbTriplet(t.popover),
      contrastText: t.popoverForeground,
    },
    card: {
      main: t.card,
      mainChannel: oklchToRgbTriplet(t.card),
      contrastText: t.cardForeground,
    },
    border: t.border,
    input: t.input,
    ring: t.ring,
  }
}

export const shadcnTheme = createTheme({
  cssVariables: {
    colorSchemeSelector: "class", // generates .light/.dark on <html>, same as shadcn
  },
  colorSchemes: {
    light: { palette: schemePalette(light) },
    dark: { palette: schemePalette(dark) },
  },
  shape: {
    borderRadius: RADIUS, // shadcn: --radius
  },
  typography: {
    fontFamily: FONT_SANS,
    button: {
      textTransform: "none",
      fontWeight: 500, // shadcn: font-medium
      fontSize: "0.875rem", // shadcn: text-sm
      lineHeight: "1.25rem",
      letterSpacing: "normal",
    },
  },
  components: {
    MuiButtonBase: {
      defaultProps: {
        disableRipple: true, // shadcn has no ripple
      },
    },
    // -----------------------------------------------------------------------
    // Button
    //
    // Ground truth: apps/showcase/src/components/ui/button.tsx (cva, style
    // "radix-nova"), read directly rather than assumed. Every value below was
    // cross-checked with getComputedStyle() on the live shadcn button (light
    // + dark, default/hover/focus-visible) - see task-7-report.md for the
    // full before/after table. The installed source has drifted from an
    // older/typical shadcn button in several load-bearing ways.
    //
    // base (all variants/sizes):
    //   group/button inline-flex shrink-0 items-center justify-center
    //   rounded-lg border border-transparent bg-clip-padding text-sm
    //   font-medium whitespace-nowrap transition-all outline-none select-none
    //   focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50
    //   active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none
    //   disabled:opacity-50 aria-invalid:* (no invalid/form-validated buttons
    //   in the gallery - out of scope) [&_svg]:pointer-events-none
    //   [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4
    //
    // variant (only what the gallery exercises: default/outline/secondary/
    // ghost/destructive/link; the icon/icon-*/xs sizes have no MUI `size`
    // equivalent and are unused - out of scope):
    //   default:     bg-primary text-primary-foreground hover:bg-primary/80
    //   outline:     border-border bg-background hover:bg-muted hover:text-foreground
    //                dark:border-input dark:bg-input/30 dark:hover:bg-input/50
    //   secondary:   bg-secondary text-secondary-foreground
    //                hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)]
    //   ghost:       (no base bg/text class) hover:bg-muted hover:text-foreground
    //                dark:hover:bg-muted/50
    //   destructive: bg-destructive/10 text-destructive hover:bg-destructive/20
    //                focus-visible:border-destructive/40 focus-visible:ring-destructive/20
    //                dark:bg-destructive/20 dark:hover:bg-destructive/30
    //                dark:focus-visible:ring-destructive/40
    //   link:        text-primary underline-offset-4 hover:underline
    //
    // size (default/sm/lg only - mapped 1:1 to MUI medium/small/large):
    //   default: h-8 gap-1.5 px-2.5                      -> 32px / 6px / 0 10px
    //   sm:      h-7 gap-1 px-2.5 text-[0.8rem]
    //            rounded-[min(var(--radius-md),12px)]     -> 28px / 4px / 0 10px / 12.8px, 8px radius
    //            [&_svg:not([class*='size-'])]:size-3.5   -> 14px icons
    //   lg:      h-9 gap-1.5 px-2.5                       -> 36px / 6px / 0 10px (font/radius/gap = default)
    //
    // Corrections vs. the Task 7 plan's first-draft code (written against an
    // older shadcn registry; wrong on every point below):
    //   - radius is rounded-lg == var(--radius) == 10px, not rounded-md
    //     (8px); only the small size drops to radius-md (8px, via the
    //     multiplicative --radius-md: calc(var(--radius) * 0.8) scale - the
    //     "min(...,12px)" cap in the source is inert at this RADIUS value).
    //   - padding-inline is px-2.5 (10px) for EVERY size, not px-3/4/6;
    //     vertical padding is always 0 (height + flex centering only, no
    //     py-* class exists).
    //   - the default/primary hover tint is bg-primary/80, not /90.
    //   - destructive is NOT a solid red button with white text. It is
    //     bg-destructive/10 with text-destructive (a pale "soft" button),
    //     hover bg-destructive/20, and its OWN focus ring
    //     (border-destructive/40, ring-destructive/20, dark ring/40)
    //     instead of the shared ring token - this was the 18%+ mismatch.
    //   - outline/ghost hover use bg-muted + text-foreground, not bg-accent.
    //   - no shadow-xs (or any shadow) appears anywhere on the installed
    //     button; SHADOW_XS above has been corrected to "none" to match and
    //     is consumed here as an explicit reset.
    //   - cursor is the browser default (no cursor-pointer class), not
    //     pointer; MUI's ButtonBase defaults to cursor:pointer, so it is
    //     forced back to match.
    //   - MUI's built-in "text" and "outlined" variants colour their label
    //     with palette.primary.main (the `color` prop default) rather than
    //     the ambient foreground text - invisible in THIS theme's default
    //     light/dark grays because pixelmatch's anti-aliasing skip absorbs
    //     the difference on thin glyph strokes, but it is a real, measured
    //     mismatch (dark: 0.922 vs 0.985 OKLCH lightness) and is fixed
    //     explicitly below rather than left to that leniency.
    // -----------------------------------------------------------------------
    MuiButton: {
      defaultProps: {
        disableElevation: true, // shadcn buttons carry no elevation shadow
      },
      styleOverrides: {
        root: ({ theme }) => ({
          minWidth: 0,
          height: "2rem", // shadcn: h-8 (default/medium size)
          padding: "0 0.625rem", // shadcn: px-2.5, uniform across sizes; no py-* (height + centering only)
          gap: "0.375rem", // shadcn: gap-1.5
          borderRadius: RADIUS, // shadcn: rounded-lg -> --radius-lg = var(--radius), 1x
          border: "1px solid transparent", // shadcn: border border-transparent
          backgroundClip: "padding-box", // shadcn: bg-clip-padding
          boxSizing: "border-box",
          whiteSpace: "nowrap",
          boxShadow: SHADOW_XS, // shadcn: no shadow on any button state
          transition: "all 150ms cubic-bezier(0.4, 0, 0.2, 1)", // shadcn: transition-all
          outline: "none",
          cursor: "default", // shadcn: no cursor-pointer class; browser default
          userSelect: "none", // shadcn: select-none
          "& svg": { width: "1rem", height: "1rem" }, // shadcn: [&_svg:not([class*='size-'])]:size-4
          "& .MuiButton-startIcon, & .MuiButton-endIcon": { margin: 0 }, // root gap does the spacing instead
          "&:focus-visible": {
            borderColor: theme.vars.palette.ring, // shadcn: focus-visible:border-ring
            boxShadow: `0 0 0 3px color-mix(in oklab, ${theme.vars.palette.ring} 50%, transparent)`, // shadcn: focus-visible:ring-ring/50 ring-3
          },
          "&.Mui-disabled": {
            opacity: 0.5, // shadcn: disabled:opacity-50 (MUI's own graying is undone per-variant below)
          },
        }),
      },
      variants: [
        {
          props: { variant: "contained", color: "primary" },
          style: ({ theme }) => ({
            backgroundColor: theme.vars.palette.primary.main, // shadcn: bg-primary
            color: theme.vars.palette.primary.contrastText, // shadcn: text-primary-foreground
            "&:hover": {
              backgroundColor: `color-mix(in oklab, ${theme.vars.palette.primary.main} 80%, transparent)`, // shadcn: hover:bg-primary/80
            },
            "&.Mui-disabled": {
              backgroundColor: theme.vars.palette.primary.main,
              color: theme.vars.palette.primary.contrastText,
            },
          }),
        },
        {
          props: { variant: "contained", color: "secondary" },
          style: ({ theme }) => ({
            backgroundColor: theme.vars.palette.secondary.main, // shadcn: bg-secondary
            color: theme.vars.palette.secondary.contrastText, // shadcn: text-secondary-foreground
            "&:hover": {
              // shadcn: hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)]
              backgroundColor: `color-mix(in oklch, ${theme.vars.palette.secondary.main}, ${theme.vars.palette.text.primary} 5%)`,
            },
            "&.Mui-disabled": {
              backgroundColor: theme.vars.palette.secondary.main,
              color: theme.vars.palette.secondary.contrastText,
            },
          }),
        },
        {
          props: { variant: "contained", color: "error" },
          style: ({ theme }) => ({
            // shadcn destructive is a pale/soft button, not solid (see banner above)
            backgroundColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 10%, transparent)`, // shadcn: bg-destructive/10
            color: theme.vars.palette.error.main, // shadcn: text-destructive
            "&:hover": {
              backgroundColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 20%, transparent)`, // shadcn: hover:bg-destructive/20
            },
            "&:focus-visible": {
              borderColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 40%, transparent)`, // shadcn: focus-visible:border-destructive/40
              boxShadow: `0 0 0 3px color-mix(in oklab, ${theme.vars.palette.error.main} 20%, transparent)`, // shadcn: focus-visible:ring-destructive/20
            },
            "&.Mui-disabled": {
              backgroundColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 10%, transparent)`,
              color: theme.vars.palette.error.main,
            },
            ...theme.applyStyles("dark", {
              backgroundColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 20%, transparent)`, // shadcn: dark:bg-destructive/20
              "&:hover": {
                backgroundColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 30%, transparent)`, // shadcn: dark:hover:bg-destructive/30
              },
              "&:focus-visible": {
                boxShadow: `0 0 0 3px color-mix(in oklab, ${theme.vars.palette.error.main} 40%, transparent)`, // shadcn: dark:focus-visible:ring-destructive/40
              },
              "&.Mui-disabled": {
                backgroundColor: `color-mix(in oklab, ${theme.vars.palette.error.main} 20%, transparent)`,
              },
            }),
          }),
        },
        {
          props: { variant: "outlined" },
          style: ({ theme }) => ({
            border: `1px solid ${theme.vars.palette.border}`, // shadcn: border-border
            backgroundColor: theme.vars.palette.background.default, // shadcn: bg-background
            color: theme.vars.palette.text.primary, // shadcn: ambient foreground (MUI defaults outlined text to primary.main)
            "&:hover": {
              backgroundColor: theme.vars.palette.muted.main, // shadcn: hover:bg-muted
              color: theme.vars.palette.text.primary, // shadcn: hover:text-foreground
            },
            "&.Mui-disabled": {
              border: `1px solid ${theme.vars.palette.border}`,
              backgroundColor: theme.vars.palette.background.default,
              color: theme.vars.palette.text.primary,
            },
            ...theme.applyStyles("dark", {
              backgroundColor: `color-mix(in oklab, ${theme.vars.palette.input} 30%, transparent)`, // shadcn: dark:bg-input/30
              borderColor: theme.vars.palette.input, // shadcn: dark:border-input
              "&:hover": {
                backgroundColor: `color-mix(in oklab, ${theme.vars.palette.input} 50%, transparent)`, // shadcn: dark:hover:bg-input/50
              },
              // shadcn: dark:border-input wins the cascade over the base
              // focus-visible:border-ring in the installed app (Tailwind
              // orders the "dark:" variant after "focus-visible:", so the
              // dark border override is not itself overridden by focus) -
              // verified with getComputedStyle: dark+focused still reads
              // border-color from --input, not --ring. The ring box-shadow
              // is unaffected (nothing else contests that property) so only
              // border-color is restated here.
              "&:focus-visible": {
                borderColor: theme.vars.palette.input,
              },
              "&.Mui-disabled": {
                backgroundColor: `color-mix(in oklab, ${theme.vars.palette.input} 30%, transparent)`,
                borderColor: theme.vars.palette.input,
              },
            }),
          }),
        },
        {
          props: { variant: "text" },
          style: ({ theme }) => ({
            color: theme.vars.palette.text.primary, // shadcn ghost: ambient foreground (MUI defaults text variant to primary.main)
            "&:hover": {
              backgroundColor: theme.vars.palette.muted.main, // shadcn ghost: hover:bg-muted
              color: theme.vars.palette.text.primary, // shadcn ghost: hover:text-foreground
            },
            "&.Mui-disabled": {
              color: theme.vars.palette.text.primary,
            },
            ...theme.applyStyles("dark", {
              "&:hover": {
                backgroundColor: `color-mix(in oklab, ${theme.vars.palette.muted.main} 50%, transparent)`, // shadcn: dark:hover:bg-muted/50
              },
            }),
          }),
        },
        {
          props: { variant: "link" },
          style: ({ theme }) => ({
            color: theme.vars.palette.primary.main, // shadcn: text-primary
            textUnderlineOffset: "4px", // shadcn: underline-offset-4
            "&:hover": {
              textDecoration: "underline", // shadcn: hover:underline
              backgroundColor: "transparent",
            },
            "&.Mui-disabled": {
              color: theme.vars.palette.primary.main,
            },
          }),
        },
        {
          props: { size: "small" },
          style: {
            height: "1.75rem", // shadcn: h-7
            gap: "0.25rem", // shadcn: gap-1
            borderRadius: `calc(${RADIUS} * 0.8)`, // shadcn: rounded-[min(var(--radius-md),12px)] -> radius-md (12px cap inert here)
            fontSize: "0.8rem", // shadcn: text-[0.8rem]
            lineHeight: 1.5, // shadcn: arbitrary size has no paired line-height; inherits Tailwind preflight's html { line-height: 1.5 }
            "& svg": { width: "0.875rem", height: "0.875rem" }, // shadcn: [&_svg:not([class*='size-'])]:size-3.5
          },
        },
        {
          props: { size: "large" },
          style: {
            height: "2.25rem", // shadcn: h-9 (padding/gap/radius unchanged from default)
            // shadcn: text-sm (unchanged from default) - MUI's own sizeLarge default
            // asserts fontSize 15px (theme.typography.pxToRem(15)) that plain
            // inheritance from typography.button does not clear, so it is
            // restated explicitly here to hold at 14px.
            fontSize: "0.875rem",
          },
        },
      ],
    },
    // -----------------------------------------------------------------------
    // IconButton
    //
    // Ground truth: apps/showcase/src/components/ui/button.tsx (same cva as
    // Button above - shadcn ships no separate IconButton component; icon-only
    // buttons are just <Button size="icon"> or one of its icon-* size
    // variants). Mapped to MUI IconButton's small/medium/large sizes using
    // the shadcn "ghost" treatment (the conventional bare icon-button look -
    // no resting background, bg-muted on hover), since IconButton has no MUI
    // `variant` prop of its own to key off.
    //
    // shadcn icon size variants consumed (verbatim from the cva above,
    // mapped small/medium/large -> icon-sm/icon/icon-lg, mirroring how
    // MuiButton's size="small"/default/"large" already map to Button's
    // sm/default/lg 28/32/36px height ladder):
    //   icon:    size-8   -> 32px square; no radius override, so it falls
    //            through to the base rounded-lg == --radius-lg == RADIUS (10px)
    //   icon-sm: size-7 rounded-[min(var(--radius-md),12px)] -> 28px square,
    //            --radius-md = RADIUS * 0.8 = 8px (the 12px cap is inert at
    //            this RADIUS value - identical formula to MuiButton's
    //            size="small" radius above)
    //   icon-lg: size-9   -> 36px square; no radius override, same RADIUS as icon
    //   (icon-xs, size-6 with its own [&_svg:...]:size-3 override, has no MUI
    //   size equivalent - unused, out of scope, same as Button's xs size)
    // Unlike Button's text sizes, none of icon/icon-sm/icon-lg carries its
    // own svg-size override (only icon-xs does), so they all fall through to
    // the shared base [&_svg:not([class*='size-'])]:size-4 - svg sizing
    // (16px) is identical across all three mapped IconButton sizes.
    //
    // variant mapped (ghost only - the shadcn convention for bare icon
    // buttons; the gallery's four pairs only exercise default/hover/disabled
    // on this treatment):
    //   ghost: (no base bg/text class) hover:bg-muted hover:text-foreground
    //          dark:hover:bg-muted/50 - identical treatment (and identical
    //          correction away from a naive bg-accent guess) to MuiButton's
    //          "text" variant above.
    //
    // MUI IconButton ships its own padding (8/5/12px by size), a circular
    // (borderRadius: 50%) shape, a `color: action.active` default text
    // color, and a ripple-gated hover halo (--IconButton-hoverBg, itself
    // already inert here because MuiButtonBase.defaultProps sets
    // disableRipple: true globally above - see the `props =>
    // !props.disableRipple` gate in MUI's IconButton source). Padding,
    // radius, size, and color are reset explicitly below; the hover halo
    // needed no extra kill switch.
    // -----------------------------------------------------------------------
    MuiIconButton: {
      styleOverrides: {
        root: ({ theme }) => ({
          width: "2rem", // shadcn: size-8 (icon, default/medium)
          height: "2rem",
          padding: 0,
          borderRadius: RADIUS, // shadcn: rounded-lg -> --radius-lg = var(--radius), 1x
          border: "1px solid transparent", // shadcn: border border-transparent
          backgroundColor: "transparent", // shadcn ghost: no base bg class
          backgroundClip: "padding-box", // shadcn: bg-clip-padding
          boxSizing: "border-box",
          color: theme.vars.palette.text.primary, // shadcn ghost: ambient foreground (MUI defaults to action.active)
          fontSize: "0.875rem", // shadcn: text-sm (base class; icon sizes carry no font-size override) - MUI IconButton otherwise sets 24/18/28px by size
          boxShadow: SHADOW_XS, // shadcn: no shadow on any button state
          transition: "all 150ms cubic-bezier(0.4, 0, 0.2, 1)", // shadcn: transition-all
          outline: "none",
          cursor: "default", // shadcn: no cursor-pointer class; browser default
          userSelect: "none", // shadcn: select-none
          "& svg": { width: "1rem", height: "1rem" }, // shadcn: [&_svg:not([class*='size-'])]:size-4
          "&:hover": {
            backgroundColor: theme.vars.palette.muted.main, // shadcn ghost: hover:bg-muted
            color: theme.vars.palette.text.primary, // shadcn ghost: hover:text-foreground
          },
          "&:focus-visible": {
            borderColor: theme.vars.palette.ring, // shadcn: focus-visible:border-ring
            boxShadow: `0 0 0 3px color-mix(in oklab, ${theme.vars.palette.ring} 50%, transparent)`, // shadcn: focus-visible:ring-ring/50 ring-3
          },
          "&.Mui-disabled": {
            opacity: 0.5, // shadcn: disabled:opacity-50 (MUI's own graying is undone below)
            color: theme.vars.palette.text.primary,
          },
          ...theme.applyStyles("dark", {
            "&:hover": {
              backgroundColor: `color-mix(in oklab, ${theme.vars.palette.muted.main} 50%, transparent)`, // shadcn: dark:hover:bg-muted/50
            },
          }),
        }),
      },
      variants: [
        {
          props: { size: "small" },
          style: {
            width: "1.75rem", // shadcn: icon-sm size-7
            height: "1.75rem",
            borderRadius: `calc(${RADIUS} * 0.8)`, // shadcn: rounded-[min(var(--radius-md),12px)] -> radius-md (12px cap inert here)
          },
        },
        {
          props: { size: "large" },
          style: {
            width: "2.25rem", // shadcn: icon-lg size-9
            height: "2.25rem",
            // radius/svg unchanged from default - icon-lg has no rounded/svg override
          },
        },
      ],
    },
    // Per-component overrides are appended by later tasks, one banner each.
  },
})
